def discard(n=-1, qid=-1, dehydration_hooks=None, hydration_hooks=None, **handlers):
    # Validate input
    if n < 0:
        raise ValueError("n must be a positive integer")
    if qid < 0:
        raise ValueError("qid must be a positive integer")

    # Create DISCARD message
    discard_message = {
        "op": "DISCARD",
        "n": n,
        "qid": qid
    }

    # Include dehydration and hydration hooks in message
    if dehydration_hooks is not None:
        discard_message["dehydration_hooks"] = dehydration_hooks
    if hydration_hooks is not None:
        discard_message["hydration_hooks"] = hydration_hooks

    # Return Response object
    return Response(discard_message, handlers)

