def round_half_to_even(n):
    """
    Return the value of `n` rounded to the nearest integer, preferring to round up for halfway values.
    :param n: a number
    :return: the rounded value
    """
    if n >= 0:
        return int(n + 0.5)
    else:
        return int(n - 0.5)

