def parse_version(s: str) -> tuple[int, ...]:
    versions = s.split(".")
    if len(versions) == 3:
        major, minor, build = versions
        return (int(major), int(minor), int(build))
    elif len(versions) == 2:
        major, minor = versions
        return (int(major), int(minor), 0)
    elif len(versions) == 1:
        major = versions
        return (int(major), 0, 0)
    else:
        raise ValueError(f"Invalid version format: {s}")

