def lfu_cache(maxsize=128, typed=False):
    def wrapper(func):
        cache = {}
        freqs = {}
        hits = {}

        def wrapper(*args, **kwargs):
            """Wrapper for the decorated function"""
            key = (args, tuple(kwargs.items()))
            if key not in cache:
                cache[key] = func(*args, **kwargs)
                freqs[key] = 1
                hits[key] = 1
            else:
                freqs[key] += 1
                hits[key] += 1
                if freqs[key] > maxsize:
                    lfu_key = min(freqs, key=freqs.get)
                    cache.pop(lfu_key)
                    freqs.pop(lfu_key)
                    hits.pop(lfu_key)
            return cache[key]

        return wrapper
    return wrapper

