def file_to_textbuffer(file_name, encoding):
    try:
        # Open the file in the specified encoding mode
        with open(file_name, mode="r", encoding=encoding) as file:
            # Read the entire file into a single string
            text = file.read()
        # Return the text as a TextBuffer object
        return TextBuffer(text)
    except (OSError, UnsupportedOperation) as e:
        # Handle the error and provide a helpful message to the user
        raise ValueError(f"Error while reading file {file_name}: {e}") from e

