def legacy_mergeOrderings(orderings):
    """
    Merge multiple orderings to preserve within-ordering order.

    Orderings are constrained such that if an object appears in two or more orderings,
    then the suffix that begins with the object must be in both orderings.

    :param orderings: list of orderings
    :return: merged ordering
    """

    if not orderings:
        return []

    merged_ordering = []
    for ordering in orderings:
        for obj in ordering:
            if obj not in merged_ordering:
                merged_ordering.append(obj)

    for ordering in orderings:
        for suffix in ordering[1:]:
            if suffix in ordering:
                merged_ordering.append(suffix)

    return merged_ordering

