def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent

    Args:
        classes (list of classes): list of classes to be reduced

    Returns:
        tuple: minimal ordered list of base classes
    """

    if not classes:
        return ()

    result = []
    for cls in classes:
        if cls not in result:
            result.append(cls)
            for base in cls.__bases__:
                result.extend(minimalBases(base))

    return tuple(result)

