class Integral:
    def __init__(self, bins, edges):
        self.bins = bins
        self.edges = edges

    def compute(self):
        """Compute the integral of the histogram."""
        integral = 0
        for i in range(len(self.bins)):
            integral += self.bins[i] * (self.edges[i+1] - self.edges[i])
        return integral

