def format(
	sql: AnyStr,
	params: Union[Dict[Union[str, int], Any], Sequence[Any]]
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
	# Use a dictionary to keep track of the positional and named arguments
	formatted_params = {}
	# Check if the in-style parameters are named or ordinal
	if isinstance(params, Mapping):
		# Move the named parameters to a dictionary
		for key, value in params.items():
			formatted_params["@" + key] = value
	else:
		# Enumerate the ordinal parameters and move them to a list
		formatted_params.extend((f"@{i+1}", value) for i, value in enumerate(params))
	# Replace the in-style parameters in the SQL query with the formatted parameters
	formatted_sql = re.sub(r"(?<=\w)\s*\?\s*", r"{}", sql).format(
		*formatted_params.keys()
	)
	return formatted_sql, formatted_params

