def int_to_string(number, alphabet, padding=None):
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, list) or not all(isinstance(i, str) for i in alphabet):
        raise TypeError("alphabet must be a list of strings")
    if padding is not None and not isinstance(padding, int):
        raise TypeError("padding must be an integer")

    digits = []
    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    if padding is not None:
        while len(digits) < padding:
            digits.insert(0, alphabet[0])

    return "".join(digits[::-1])

