def dict_insert(dic, val, key, *keys):
    # check if the first key is valid
    if key not in dic:
        raise KeyError(f"key {key} is not present in the dictionary")

    # if there are subkeys, recursively insert the value
    if keys:
        dict_insert(dic[key], val, *keys)
    else:
        dic[key] = val

    return dic

