def list_of_file_names(settings_dirs, spec_option):
    """
    Generate a list of file names for the given settings directories.

    Args:
        settings_dirs (list[str]): The directories to search for settings files.
        spec_option (str): The option name of the specification.

    Returns:
        list[str]: The list of file names.
    """

    file_names = []
    for settings_dir in settings_dirs:
        for root, dirs, files in os.walk(settings_dir):
            for file in files:
                if file.endswith(".toml"):
                    file_names.append(os.path.join(root, file))

    return file_names

