def validate_from_content(cls, spec_content):
        """validate that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        try:
            spec_dict = yaml.safe_load(spec_content)
            if not spec_dict.get("tag"):
                raise IRValidatorException("Missing Tag")
            if not spec_dict.get("version"):
                raise IRValidatorException("Missing version number")
            if not spec_dict.get("platform"):
                raise IRValidatorException("Missing platform information")
            if not spec_dict.get("platform_version"):
                raise IRValidatorException("Missing platform version information")
            if not spec_dict.get("modules"):
                raise IRValidatorException("Missing modules information")
            if not spec_dict.get("schema"):
                raise IRValidatorException("Missing schema information")
            if not spec_dict.get("rules"):
                raise IRValidatorException("Missing rules information")
            return spec_dict
        except yaml.YAMLError as e:
            raise IRValidatorException("Error reading input file: {}".format(e))

