def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name.

    Args:
        command_name (str): The name of the command.
        argument_name (str): The name of the option.

    Returns:
        OptionSpec: The specification of the option.

    Raises:
        ValueError: If the specified command or option does not exist.
    """
    if not self._specs:
        raise ValueError("No specifications have been loaded")

    try:
        return self._specs[command_name]["options"][argument_name]
    except KeyError:
        raise ValueError(f"Specified command {command_name} does not exist") from None
    except KeyError:
        raise ValueError(f"Specified option {argument_name} not found in {command_name}") from None

    return OptionSpec(name=argument_name, spec=self._specs[command_name]["options"][argument_name])

