def get_nested_custom_and_control_args(args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """

    control_args = {}
    nested_args = {}
    custom_args = {}

    # Check if the arg is a nested argument
    if args.get("nested"):
        # Extract the nested arguments
        nested_args = args["nested"]
    else:
        # Check if the arg is a custom argument
        if args.get("custom"):
            # Extract the custom arguments
            custom_args = args["custom"]

    # Remove the nested and custom arguments from the original list of args
    args = {k: v for k, v in args.items() if k not in ("nested", "custom")}

    # Check if there are any remaining arguments to be added to the control_args
    if args:
        # Create a flat dict of control args
        control_args = {k: v for k, v in args.items()}

    # Return the nested, custom and control args
    return nested_args, custom_args, control_args

